// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {
        address nonOwner = address(0x123);

        vm.prank(nonOwner);
        bool ok;
        try c.addReward(address(0x456)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok, "non-owner should not be able to add reward");
    }
}
